#!/bin/zsh
# Builds a Release Attic.app into ./dist (regenerating the Xcode project
# first, since it's gitignored and generated by xcodegen).
#
#   scripts/build.sh          build to dist/Attic.app
#   scripts/build.sh --open   build, then launch it
set -euo pipefail

ROOT="${0:A:h:h}"
DERIVED="$ROOT/.build-xcode"
DIST="$ROOT/dist"

cd "$ROOT"
xcodegen generate --quiet
xcodebuild \
    -project Attic.xcodeproj \
    -scheme Attic \
    -configuration Release \
    -destination 'platform=macOS' \
    -derivedDataPath "$DERIVED" \
    -allowProvisioningUpdates \
    -quiet \
    build

rm -rf "$DIST/Attic.app"
mkdir -p "$DIST"
ditto "$DERIVED/Build/Products/Release/Attic.app" "$DIST/Attic.app"
echo "Built $DIST/Attic.app"

if [[ "${1:-}" == "--open" ]]; then
    # Quit any running copy first so `open` launches the fresh build
    # rather than just focusing the old one.
    osascript -e 'quit app "Attic"' 2>/dev/null || true
    open "$DIST/Attic.app"
fi
